"""Build a portable, source-linked research report from the reviewed selections."""
import collections,csv,gzip,hashlib,html,json,shutil
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
RUN=ROOT/'docs/research/balkans-deep-20261011'
BACKUP=Path('/Users/vadimdulub/Library/Application Support/Artline/backups/balkans-deep-20261011')
def load(p):
    b=p.read_bytes();return json.loads(gzip.decompress(b)if p.suffix=='.gz'else b)
def save(name,data): (RUN/name).write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
def e(x):return html.escape(str(x or''),quote=True)
def link(u,label):return '<a href="'+e(u)+'" target="_blank" rel="noopener">'+e(label)+'</a>'
country={'GR':'Greece','BG':'Bulgaria','MK':'North Macedonia'}
plan=load(BACKUP/'wave1-plan.json.gz');review=load(RUN/'wave1-record-review.json');excluded={x['key']for x in review['excluded']}
facts=[dict(x['fact'],wave='wave1',artwork_id=x['artwork_id'])for x in plan['records']if x['fact']['key']not in excluded]
museums={k:v['evidence']for k,v in plan['museums'].items()}
for wave in ['wave2','wave3']:
    prep=load(RUN/(wave+'-research-preparation.json'));selection=load(RUN/('selection-'+wave+'.json'))
    facts.extend(dict(x['fact'],wave=wave,artwork_id=x['artwork_id'])for x in prep['records'])
    museums.update({x['slug']:x for x in selection['museums']})
images=[x for w in ['wave1','wave2','wave3']for x in load(RUN/(w+'-images-reviewed.json'))]
imby={x['key']:x for x in images};(RUN/'images').mkdir(exist_ok=True)
assert len({f['key']for f in facts})==len(facts)
for f in facts:
    if f['key']in imby:
        im=imby[f['key']];raw=Path(im['visual_path']).read_bytes();assert len(raw)<=100000 and hashlib.sha256(raw).hexdigest()==im['sha256']
        shutil.copyfile(im['visual_path'],RUN/'images'/(im['artwork_id']+'.jpg'))
        f['report_image']='images/'+im['artwork_id']+'.jpg';f['image_view']=im['view_label'];f['image_credit']=im['creator_credit'];f['image_rights']=im['rights_label'];f['image_source']=im['image_url']
    f['country_code']=museums[f['museum_slug']]['country_code'];f['museum_name']=museums[f['museum_slug']]['name']
    f['delivery_state']='Prepared; production attachment pending authentication'
    if f['wave']!='wave1':f['delivery_state']+=' and live duplicate/preimage check'
ledger=load(RUN/'country-directory-ledger-reviewed.json')['records'];baseline=load(RUN/'baseline.json.gz')
by=collections.defaultdict(list)
for f in facts:by[f['museum_slug']].append(f)
stats=dict(selected_artworks=len(facts),selected_museums=len(by),prepared_images=len(images),illustrated_museums=len({x['museum_slug']for x in images}),directory_entries=len(ledger),storage_uploads_verified=len(list((RUN/'storage').glob('*.json'))),production_artwork_writes=0,local_database_writes=0,countries={cc:dict(artworks=sum(f['country_code']==cc for f in facts),museums=sum(museums[k]['country_code']==cc for k in by),images=sum(museums[x['museum_slug']]['country_code']==cc for x in images),directory_entries=sum(x['country']==cc for x in ledger))for cc in country})
save('report-summary.json',stats)
save('report-design.json',dict(colors={'paper':'#ffffff','sea_glass':'#edf4f7','aegean':'#1d4264','ink':'#172c3b','stone':'#dce3e8','icon_gold':'#a68135'},type={'display':'Baskerville / Georgia serif','body':'Avenir Next / system sans-serif'},layout='Left-aligned research atlas: a large uncropped icon opens the page beside the scope; museum entries pair an artwork with an expandable list of documented objects. Search filters local report entries only.',wireframe='[ title and scope | authentic icon ]\n[ country comparison ]\n[ country / museum / artist search ]\n[ museum image | collection explanation + object list ]\n[ existing coverage / directory ledger / research decisions ]',review='Replaced generic statistics-led cards with a catalogue image and collection descriptions. Gold appears only as a quiet icon-related accent. No image crops, decorative labels, generated artwork, gradients or repeated shadow boxes.'))
fields=['country','museum','city','title','creator','date','year_start','year_end','medium','dimensions','accession','source_url','locator','image','image_source','image_view','rights','status']
with(RUN/'selected-artworks.csv').open('w',newline='',encoding='utf-8-sig')as out:
    wr=csv.DictWriter(out,fieldnames=fields);wr.writeheader()
    for f in facts:wr.writerow(dict(country=country[f['country_code']],museum=f['museum_name'],city=museums[f['museum_slug']]['city'],title=f['title'],creator=f['creator']or'Unidentified in source',date=f['date_display'],year_start=f['start'],year_end=f['end'],medium=f['medium'],dimensions=f['dimensions'],accession=f['accession'],source_url=f['source_url'],locator=f['locator'],image=f.get('report_image',''),image_source=f.get('image_source',''),image_view=f.get('image_view',''),rights=f.get('image_rights',''),status=f['delivery_state']))
with(RUN/'museum-directory.csv').open('w',newline='',encoding='utf-8-sig')as out:
    wr=csv.DictWriter(out,fieldnames=['country','name','city_or_region','source','research_state']);wr.writeheader()
    for x in ledger:wr.writerow(dict(country=country[x['country']],name=x['name'],city_or_region=x.get('city'),source=x['source'],research_state=x['status']))
save('report-artworks.json',facts)
intros={
'gr-archaeological-museum-pella':'Greek Macedonia is included here. Terracotta figures, sculpture, painted decoration and the lion-hunt mosaic are documented in the palace project’s museum collection captions.',
'gr-archaeological-museum-piraeus':'The illustrated museum catalogue supports ten ancient works, including the bronze Athena and two distinct bronze Artemis statues. The two Artemis figures remain separate records.',
'gr-archaeological-museum-eleusis':'Six sculptures and reliefs from the museum catalogue. The Caryatid is the Eleusis example; the other surviving Caryatid is in Cambridge. The Great Eleusinian Relief in Athens is excluded from this museum selection.',
'bg-national-gallery-sofia':'Bulgarian and international collection highlights, with selected paintings, drawings and sculpture. Creator qualifications and undated works remain explicit. The Christian art collection is listed separately below.',
'bg-museum-christian-art-sofia':'A substantial selection of Byzantine and Bulgarian icons. A two-sided icon is one physical work; separate photographs of its sides do not create extra artworks.',
'bg-ruse-art-gallery':'Works from the gallery’s founders and twentieth-century Bulgarian art collections. Repeated objects across the two online collection lists were reconciled.',
'bg-sofia-city-art-gallery':'Four dated paintings from the museum’s painting collection page. The later work is retained as metadata under the 1970 cutoff; only the earlier works receive images in this pass.',
'bg-dimitar-dobrovich-sliven':'Two selected collection works. Nikola Tanev’s Karlovo Courtyard is held separately because an existing record with the same title has a different year.',
'bg-kazanlak-art-gallery':'Ten eligible works verified against individual object dates. The website’s date-filter results also contained later works, which were excluded. Ahinora is a separate existing-record reconciliation.',
'bg-national-archaeological-museum':'Three documented museum objects: Apollo’s altar, a bronze Zeus and a medieval lion slab. The Zeus photograph is an upper-body detail. Temporary exhibition presence alone was not accepted as ownership.',
'bg-stara-zagora-art-gallery':'Nikola Kozhuharov’s In the Realm of the Dragon (1921), supported by the gallery’s own account. The available photograph shows a figure detail; it is labelled accordingly.',
'mk-museum-contemporary-art-skopje':'Fifty-five works from the museum’s collection records, including early works within Artline’s scope. A crossed-out placeholder and files labelled as upscaled were excluded from the approved images.',
'mk-national-gallery':'Thirty-four works with explicit National Gallery ownership in the 2013 Macedonian Profane Painting catalogue. Private lenders and works owned by regional museums are assigned separately.',
'mk-city-museum-skopje':'Five paintings documented as museum property, plus two Roman ceramic lamps from Scupi. The lamps are independently identified by their grave numbers and iconography.',
'mk-institute-museum-prilep':'Dicho Zograph’s Samoil (1854), illustrated in the National Gallery’s 2013 catalogue and explicitly assigned to the Prilep museum.',
'mk-national-museum-veles':'Papradiški’s Portrait of Risto Kopandanov (1925–1930) has explicit museum ownership in the catalogue. A matching artwork photograph remains unresolved.',
'mk-museum-kumanovo':'Three paintings by Trajko Muftinski have explicit museum ownership in the catalogue: two distinct landscapes and A Basket of Apples. Matching photographs remain unresolved.',
'mk-icon-gallery-tetovo':'Papradiški’s Portrait of Abbot Ezekilj (circa 1927) belongs to the icon gallery according to the catalogue. This church collection is distinct from Tetovo’s other art institutions.',
'mk-icon-gallery-novo-selo-stip':'Theodosy Zograph’s The Appearance of the New Miracle of the Holy Virgin is illustrated and assigned to this cathedral icon gallery. The catalogue’s alternative 1813 / 1828 dating is preserved.',
'mk-institute-museum-ohrid':'Gold earrings with African-head terminals from Gorna Porta. The publication explicitly identifies the Ohrid museum as owner; the icon gallery is listed as a separate collection site.',
'mk-national-institution-stobi':'A second-century votive relief addressed to Isis and Serapis as listening gods. The publication identifies the National Institution Stobi as owner; objects from Stobi now in Belgrade are excluded.',
'mk-icon-gallery-ohrid':'Three early Byzantine icons from Milcho Georgievski’s museum catalogue: Saints Basil and Nicholas, the Forty Martyrs, and the Communion of the Apostles. Inventory numbers secure each object’s identity.'}
preferred={'gr-archaeological-museum-piraeus':'Piraeus Athena','gr-archaeological-museum-eleusis':'The Fleeing Maiden','mk-icon-gallery-ohrid':'Saint Basil the Great and Saint Nicholas'}
def figure(f,hero=False):
    if not f.get('report_image'):return '<div class="image-gap"><strong>Artwork photograph still needed</strong><p>Ownership is documented. No verified image of this object was found in the reviewed sources.</p></div>'
    return '<figure><a href="'+e(f['report_image'])+'" target="_blank"><img src="'+e(f['report_image'])+'" alt="'+e(f['title']+' — '+f['image_view'])+'" loading="'+('eager'if hero else'lazy')+'"></a><figcaption><strong>'+e(f['title'])+'</strong><br>'+e(f['date_display'])+'<br>'+e(f['image_credit'])+'<br>'+link(f['source_url'],'Artwork source')+'</figcaption></figure>'
sections=[]
for slug,fs in sorted(by.items(),key=lambda kv:(list(country).index(museums[kv[0]]['country_code']),museums[kv[0]]['name'])):
    mu=museums[slug];illustrated=[f for f in fs if f.get('report_image')];feature=next((f for f in illustrated if f['title']==preferred.get(slug)),next(iter(illustrated),fs[0]));works=[]
    for f in fs:
        meta='; '.join(str(v)for v in [f['medium'],f['dimensions'],'Inventory '+f['accession']if f['accession']else None]if v)
        note=f.get('date_evidence_note')or f.get('identity_review')or''
        works.append('<div class="work"><div class="work-head"><h4>'+e(f['title'])+'</h4><p>'+e(f['creator']or'Maker not identified in the cited source')+'</p><p>'+e(f['date_display'])+'</p></div>'+('<a class="thumbnail" href="'+e(f['report_image'])+'" target="_blank"><img src="'+e(f['report_image'])+'" alt="'+e(f['title'])+'" loading="lazy"></a>'if f.get('report_image')else'')+'<div class="work-source"><p>'+e(meta)+'</p><p>'+e(note)+'</p><p>'+link(f['source_url'],'Object evidence')+'<br>'+e(f['locator'])+'</p>'+('<p class="image-note">'+e(f['image_view'])+'<br>'+e(f['image_rights'])+'</p>'if f.get('report_image')else'<p class="image-note">No approved photograph prepared.</p>')+'</div></div>')
    hay=' '.join([mu['name'],mu['city'],country[mu['country_code']]]+[str(f['title'])+' '+str(f.get('creator')or'')for f in fs])
    sections.append('<article class="museum" id="'+e(slug)+'" data-country="'+mu['country_code']+'" data-search="'+e(hay.lower())+'"><div class="museum-picture">'+figure(feature)+'</div><div class="museum-content"><p class="location">'+e(country[mu['country_code']]+' / '+mu['city'])+'</p><h3>'+e(mu['name'])+'</h3><p class="intro">'+e(intros.get(slug,''))+'</p><p class="count">'+str(len(fs))+' selected works / '+str(len(illustrated))+' artwork images</p><p>'+link(mu['website_url'],'Museum or collection reference')+'</p><details><summary>Explore '+str(len(fs))+' works and their sources</summary>'+''.join(works)+'</details></div></article>')
hero=next(f for f in facts if f['key']=='ohrid-icons-1999/272')
rows=''.join('<tr><th>'+country[cc]+'</th><td>'+str(s['museums'])+'</td><td>'+str(s['artworks'])+'</td><td>'+str(s['images'])+'</td></tr>'for cc,s in stats['countries'].items())
base_rows=''.join('<tr><td>'+link(x['website_url'],x['name'])+'</td><td>'+e(x['city'])+'</td><td>'+str(x['artworks'])+'</td><td>'+str(x['images'])+'</td></tr>'for x in baseline['museums'])
dir_rows=''.join('<tr data-country="'+x['country']+'" data-search="'+e((x['name']+' '+(x.get('city')or'')).lower())+'"><td>'+country[x['country']]+'</td><td>'+link(x['source'],x['name'])+'</td><td>'+e(x.get('city'))+'</td></tr>'for x in ledger)
